css:
.forum-page {
  min-height: 100vh;
  background: linear-gradient(180deg, #f8f9fc 0%, #f1f3f8 100%);
  font-family: "Noto Sans SC", "PingFang SC", "Microsoft YaHei", sans-serif;
}
.forum-main {
  max-width: 1300px;
  margin: 0 auto;
  padding: 24px 32px 40px;
}
.forum-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}
.forum-header h2 {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 22px;
  font-weight: 800;
  color: #1a2b5f;
  margin: 0;
}
.post-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 12px 24px;
  border: none;
  border-radius: 12px;
  background: linear-gradient(135deg, #c41e3a, #e8384f);
  color: #ffffff;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.3s;
  box-shadow: 0 2px 12px rgba(196, 30, 58, 0.3);
}
.post-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 18px rgba(196, 30, 58, 0.4);
}
.forum-body {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 24px;
}
.forum-left {
  background: #ffffff;
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 2px 12px rgba(26, 43, 95, 0.04);
}
.category-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}
.cat-btn {
  padding: 8px 16px;
  border: 1px solid #e8eaf0;
  border-radius: 20px;
  background: #f8f9fc;
  font-size: 13px;
  font-weight: 600;
  color: #5a6488;
  cursor: pointer;
  transition: all 0.3s;
  display: flex;
  align-items: center;
  gap: 6px;
}
.cat-btn:hover {
  border-color: #1a2b5f;
  color: #1a2b5f;
}
.cat-btn.active {
  background: #1a2b5f;
  color: #ffffff;
  border-color: #1a2b5f;
}
.cat-count {
  font-size: 11px;
  opacity: 0.7;
}
.post-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.post-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 16px;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.3s;
  border: 1px solid transparent;
}
.post-item:hover {
  background: #f8f9fc;
  border-color: #e8eaf0;
}
.post-avatar {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: linear-gradient(135deg, #eef2ff, #e0e7ff);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.avatar-emoji {
  font-size: 22px;
}
.post-content {
  flex: 1;
  min-width: 0;
}
.post-title {
  font-size: 15px;
  font-weight: 700;
  color: #1a2b5f;
  margin: 0 0 6px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.post-excerpt {
  font-size: 12px;
  color: #8a8faa;
  margin: 0 0 8px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.post-meta {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: #8a8faa;
}
.meta-dot {
  color: #d1d5db;
}
.post-tag {
  padding: 4px 10px;
  border-radius: 8px;
  font-size: 11px;
  font-weight: 600;
  color: #1a2b5f;
  white-space: nowrap;
  flex-shrink: 0;
}
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid #f0f2f5;
}
.pagination button {
  padding: 6px 16px;
  border: 1px solid #e8eaf0;
  border-radius: 8px;
  background: #ffffff;
  cursor: pointer;
  font-size: 13px;
  color: #1a2b5f;
  transition: all 0.2s;
}
.pagination button:hover:not(:disabled) {
  background: #f0f2f5;
}
.pagination button:disabled {
  opacity: 0.5;
  cursor: default;
}
.page-info {
  font-size: 13px;
  color: #5a6488;
}
.forum-right {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.right-card {
  background: #ffffff;
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 2px 10px rgba(26, 43, 95, 0.04);
}
.right-card h4 {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 700;
  color: #1a2b5f;
  margin: 0 0 14px;
}
.hot-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
  border-bottom: 1px solid #f8f9fc;
  cursor: pointer;
  font-size: 12px;
  transition: all 0.2s;
}
.hot-item:hover {
  background: #f8f9fc;
  border-radius: 8px;
  padding-left: 8px;
}
.hot-rank {
  width: 20px;
  height: 20px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  color: #ffffff;
  flex-shrink: 0;
}
.hot-rank.rank-1 {
  background: #ef4444;
}
.hot-rank.rank-2 {
  background: #f97316;
}
.hot-rank.rank-3 {
  background: #f59e0b;
}
.hot-rank.rank-4, .hot-rank.rank-5 {
  background: #94a3b8;
}
.hot-title {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: #1a2b5f;
}
.hot-replies {
  font-size: 10px;
  color: #8a8faa;
  flex-shrink: 0;
}
.stats-grid {
  display: flex;
  justify-content: space-around;
}
.stats-item {
  text-align: center;
}
.stats-number {
  display: block;
  font-size: 22px;
  font-weight: 900;
  color: #1a2b5f;
  font-family: "DIN Alternate", sans-serif;
}
.stats-label {
  font-size: 11px;
  color: #8a8faa;
}
/* Modal */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2000;
}
.modal-card {
  background: #ffffff;
  border-radius: 16px;
  padding: 28px;
  width: 520px;
  max-width: 90vw;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.2);
}
.modal-card h3 {
  font-size: 18px;
  font-weight: 800;
  color: #1a2b5f;
  margin: 0 0 20px;
}
.modal-input, .modal-textarea, .modal-select {
  width: 100%;
  padding: 12px;
  border: 1px solid #e8eaf0;
  border-radius: 10px;
  font-size: 13px;
  margin-bottom: 14px;
  outline: none;
  color: #1a2b5f;
  box-sizing: border-box;
}
.modal-textarea {
  resize: vertical;
}
.modal-actions {
  display: flex;
  gap: 12px;
  justify-content: flex-end;
  margin-top: 8px;
}
.cancel-btn {
  padding: 10px 20px;
  border: 1px solid #e8eaf0;
  border-radius: 10px;
  background: #ffffff;
  font-size: 13px;
  font-weight: 600;
  color: #5a6488;
  cursor: pointer;
}
.confirm-btn {
  padding: 10px 20px;
  border: none;
  border-radius: 10px;
  background: linear-gradient(135deg, #1a2b5f, #1e3470);
  color: #ffffff;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}

loadStats.value:
async function() {
  try {
    const res = await fetch('/api/forum/stats');
    const data = await res.json();
    this.state.forumStats = { posts: data.posts || 0, users: data.users || 0, online: data.online || 0 };
  } catch (e) {}
}

submitPost.value:
async function() {
  if (!this.state.newPost.title.trim()) { ElMessage.warning('请输入标题'); return; }
  if (!this.state.newPost.content.trim()) { ElMessage.warning('请输入内容'); return; }
  const auth = window.__VTJ_AUTH__;
  if (!auth || !auth.isLoggedIn()) { ElMessage.warning('请先登录后发帖'); return; }
  this.state.submitting = true;
  try {
    const formData = new FormData();
    formData.append('title', this.state.newPost.title.trim());
    formData.append('content', this.state.newPost.content.trim());
    formData.append('share_type', 'EXPERIENCE');
    if (this.state.newPost.attachments.length) {
      formData.append('attachments', JSON.stringify(this.state.newPost.attachments));
    }
    const res = await auth.apiFetch('/api/forum/posts', { method: 'POST', body: formData });
    const data = await res.json();
    if (!res.ok) {
      ElMessage.error(data.message || data.detail || '发布失败');
      return;
    }
    this.state.posts.unshift(this._mapPost(data));
    this.state.total += 1;
    this.state.showNewPost = false;
    this.state.newPost = { title: '', content: '', attachments: [] };
    ElMessage.success('发布成功!');
  } catch (e) {
    ElMessage.error('网络错误,发布失败');
  } finally {
    this.state.submitting = false;
  }
}

handleFileUpload.value:
async function(e) {
  const files = Array.from(e.target.files || []);
  const auth = window.__VTJ_AUTH__;
  if (!auth || !auth.isLoggedIn()) { ElMessage.warning('请先登录'); return; }
  for (const file of files) {
    const formData = new FormData();
    formData.append('file', file);
    try {
      const res = await auth.apiFetch('/api/forum/upload', { method: 'POST', body: formData });
      const data = await res.json();
      if (res.ok) {
        this.state.newPost.attachments.push(data);
        ElMessage.success(`${file.name} 上传成功`);
      } else {
        ElMessage.error(data.message || data.detail || `${file.name} 上传失败`);
      }
    } catch (err) {
      ElMessage.error(`${file.name} 上传失败`);
    }
  }
  e.target.value = '';
}

toggleLike.value:
async function(post) {
  const auth = window.__VTJ_AUTH__;
  if (!auth || !auth.isLoggedIn()) { ElMessage.warning('请先登录后点赞'); return; }
  try {
    const res = await auth.apiFetch(`/api/forum/posts/${post.id}/like`, { method: 'POST' });
    if (res.ok) {
      const data = await res.json();
      post.liked = data.liked;
      post.likeCount = data.likeCount;
    }
  } catch (e) {}
}

viewUser.value:
async function(userId) {
  if (!userId) return;
  try {
    const res = await fetch(`/api/forum/users/${userId}/public`);
    if (!res.ok) { ElMessage.error('获取用户信息失败'); return; }
    const data = await res.json();
    this.state.userProfile = data;
    this.state.showUserProfile = true;
  } catch (e) {
    ElMessage.error('获取用户信息失败');
  }
}

viewPost.value:
function(post) {
  ElMessage && ElMessage.info('帖子详情功能开发中: ' + post.title);
}

formatTime.value:
function(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

formatFileSize.value:
function(bytes) {
  if (!bytes) return '0B';
  if (bytes < 1024) return bytes + 'B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + 'KB';
  return (bytes / 1024 / 1024).toFixed(1) + 'MB';
}

openNewPost.value:
function() {
  const auth = window.__VTJ_AUTH__;
  if (!auth || !auth.isLoggedIn()) { ElMessage.warning('请先登录后发帖'); return; }
  this.state.showNewPost = true;
}

_mapPost.value:
function(p) {
  return {
    id: p.id,
    title: p.title || '',
    content: p.content || '',
    author: (p.user && p.user.nickname) || '匿名',
    avatar: (p.user && p.user.avatar) || '',
    date: this.formatTime(p.createTime),
    likeCount: p.likeCount || 0,
    commentCount: p.commentCount || 0,
    viewCount: p.viewCount || 0,
    liked: p.liked || false,
    attachments: p.attachments || [],
    userId: p.user && p.user.id
  };
}

hotPosts.value:
function() {
  return [...this.state.posts]
    .sort((a, b) => (b.likeCount + b.commentCount * 2) - (a.likeCount + a.commentCount * 2))
    .slice(0, 5)
    .map((p, i) => ({ ...p, rank: i + 1 }));
}
